import os
import jinja2


def render_template_to_file(template_path, output_path, **template_params):
    """
    Render jinja2 template and save it to file

    :param template_path: path to template
    :param output_path: path to output file
    :param template_params:
            force_linefeed: allows to disable restoring of CRLF
            other parameters are passed as context to jinja2
    """
    template_dir, template_name = os.path.split(template_path)
    env = jinja2.Environment(loader=jinja2.FileSystemLoader(template_dir))
    template = env.get_template(template_name)
    force_linefeed = template_params.get("force_linefeed", True)
    if "force_linefeed" in template_params:
        del template_params['force_linefeed']
    file_content = template.render(template_params)
    if not force_linefeed:
        file_content = file_content.replace('\n', '\r\n')
    _save_template(file_content, output_path)


def _save_template(file_content, output_path):
    with open(output_path, mode="w+") as output:
        output.write(file_content)
